void UpdateStreaming(Vector3 player, Vector3 view)
{
    foreach (Cell c in grid.CellsNear(player, unloadRadius + cellSize))
    {
        float d = Vector3.Distance(c.Center, player);
        if (c.State == CellState.Unloaded && d <= loadRadius)
            Enqueue(c, Priority(c, player, view));
        else if (c.State == CellState.Loaded && d > loadRadius)
            Release(c);
    }
}

public struct GameState {
    public int Frame; public uint Rng;
    public Fighter P1, P2;
}
public static void Step(ref GameState s, ushort in1, ushort in2) {
    s.Frame++;
    Apply(ref s.P1, in1);
    Apply(ref s.P2, in2);
    if (Hit(s.P1, s.P2))
        s.P2.Hp -= 80 + UnityEngine.Random.Range(0, 11);
}
